head.script:
// DOM 요소 조회(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};

scwin.checkEl = function(id) {
	if (scwin.__getDom(id)) {
		return true;
	}
	return false;
};

scwin.getLog2 = function() {
	return '<list id="dataList1"><map index="0"><col1>1</col1><col2>4</col2><col3>7</col3><rowStatus statusValue="0">R</rowStatus></map><map index="1"><col1>2</col1><col2>5</col2><col3>8</col3><rowStatus statusValue="0">R</rowStatus></map><map index="2"><col1>3</col1><col2>6</col2><col3>9</col3><rowStatus statusValue="0">R</rowStatus></map></list>';
};

scwin.checktype = function() {
	return typeof popup_window_wframe;
};

scwin.checkVal = function() {
	return localStorage.getItem('log1') == scwin.getLog2();
};

scwin.checkVal2 = function() {
	return localStorage.getItem('log') == 'true';
};

scwin.checkVal3 = function() {
	var log2 = localStorage.getItem('log2');
	if (log2.indexOf('/sample/common_link/wframe_SKT-588_(WSQ-2568)_popup_param.xml') != -1) {
		return true;
	} else {
		return false;
	}
};

xf:trigger.script:
requires("uiplugin.popup");
var opts = {
	"id" : "popup_window_wframe",
	"type" : "window",
	"width" : 300 + "px",
	"height" : 300 + "px",
	"top" : 250,
	"left" : 250,
	"popupName" : "popup_wframe",
	"modal" : false,
	"useIFrame" : true,
	"title" : "paramTest",
	"frameMode" : "wframe",
	"xml" : dataList1.getAllXML()
};
WebSquare.util.openPopup("/sample/common_link/wframe_SKT-588_(WSQ-2568)_popup_param.xml", opts);
